"""Remove ONLY XML backups generated by this KNULLI Auto Scraper.

This does not remove current gamelist.xml, ROMs, scraped images/videos,
Skyscraper caches, manual backups, or user data. Runs once after ADB connect.
"""
from __future__ import annotations

from pathlib import Path
import re

import core


# Versions up to v0.8.5 wrote these two exact backup families.
STAMP = r'\d{8}_\d{6}(?:_\d{6})?'
LOCAL_XML = re.compile(r'([a-z][a-z0-9]*)_(' + STAMP + r')\.xml\Z')
REMOTE_XML = re.compile(r'gamelist\.xml\.knulli-autoscraper-(' + STAMP + r')\.bak\Z')


def remove_local_backups(work: Path) -> int:
    """Delete files from only the app's work/xml_backups folder.

    Guard against symlinked directories/files and unrelated files that a user
    might have placed there. A file must match our known system and timestamp.
    """
    folder = Path(work) / 'xml_backups'
    if not folder.exists() and not folder.is_symlink():
        return 0
    if folder.is_symlink() or not folder.is_dir():
        raise RuntimeError('xml_backups 경로가 정상 폴더가 아니어서 삭제하지 않았습니다.')
    removed = 0
    for path in folder.iterdir():
        match = LOCAL_XML.fullmatch(path.name)
        if not match or match.group(1) not in core.SYSTEM_IDS:
            continue
        if path.is_symlink() or not path.is_file():
            continue
        path.unlink()
        removed += 1
    # Do not remove the folder if other (possibly user-created) files exist.
    if not any(folder.iterdir()):
        folder.rmdir()
    return removed


def remove_device_backups(adb, root: str) -> int:
    """Find and remove only our tagged gamelist.xml backup files.

    Each system is scanned in its own short ASCII-only shell call; no huge
    shell commands and no recursive deletion are used.
    """
    root = root.rstrip('/')
    if not root.startswith('/') or '..' in root.split('/'):
        raise ValueError('Invalid ROM root for backup cleanup')
    core.sq(root)
    removed = 0
    for system in sorted(core.SYSTEM_IDS):
        system_dir = root + '/' + system
        prefix = system_dir + '/gamelist.xml.knulli-autoscraper-'
        # Only a wildcard suffix is unquoted, so expansion stays within the
        # exact system directory and cannot execute path text as shell code.
        command = (
            'for f in ' + core.sq(prefix) + '*.bak; do '
            '[ -f "$f" ] && [ ! -L "$f" ] || continue; '
            'printf "%s\\n" "$f"; done'
        )
        listing = adb.shell(command, timeout=35)
        for remote in listing.splitlines():
            if not remote.startswith(prefix):
                raise RuntimeError('예상하지 못한 백업 목록 응답입니다. 삭제를 중단합니다.')
            filename = remote[len(system_dir)+1:]
            if not REMOTE_XML.fullmatch(filename):
                # Preserve unrelated similarly named backups.
                continue
            quoted = core.sq(remote)
            result = adb.shell(
                'if [ -f ' + quoted + ' ] && [ ! -L ' + quoted + ' ]; then '
                'rm -f ' + quoted + ' || exit 1; printf REMOVED; '
                'else printf SKIPPED; fi', timeout=35
            ).strip()
            if result == 'REMOVED':
                removed += 1
            elif result != 'SKIPPED':
                raise RuntimeError('기기 백업 파일 삭제 응답이 비정상적입니다.')
    return removed


def cleanup(adb, config: dict, work: Path) -> dict:
    """One-time cleanup on connected device and current app work folder."""
    root = config.get('remote_root', '/userdata/roms')
    device_count = remove_device_backups(adb, root)
    local_count = remove_local_backups(work)
    return {'device_removed': device_count, 'local_removed': local_count}
